{
  "items": [
    {
      "title": "Duisburg Social Report 2007 (Sozialbericht Duisburg 2007)",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "An official municipal report containing extensive statistical tables on community life and socioeconomic conditions in Duisburg during the early 2000s. Includes neighborhood-level population statistics for 2000, demographic characteristics, nationality, employment, and social conditions. Particularly useful for comparing living conditions across Duisburg's urban districts and less densely populated neighborhoods."
    },
    {
      "title": "Duisburg Social Report 2008 (Sozialbericht Duisburg 2008)",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "Provides detailed neighborhood-level statistics on Duisburg's social structure during the 2000s. Covers employment, unemployment, migration, youth welfare, housing insecurity, and socioeconomic inequalities. Includes historical observations from 2005 and 2006, making it especially relevant for studying community development and differences in urban living conditions."
    },
    {
      "title": "Duisburg Social Report 2010: Housing and Urban Living Conditions (WohnVision)",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "An official city report focusing on housing conditions and residential development in Duisburg. Its WohnVision theme examines housing and urban development, providing evidence relevant to residential quality, neighborhood differences, and changing living conditions around the end of the 2000s. Particularly valuable for researching urban communities and residential environments."
    },
    {
      "title": "Duisburg Social Report 2012: Population Development 2000–2010",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "Contains historical demographic statistics covering 2000–2010, including population changes by sex, nationality, and administrative district. Although published in 2012, its historical tables directly cover the requested decade. Useful for examining population decline, demographic transformation, migration, and community composition across Duisburg's neighborhoods."
    },
    {
      "title": "Duisburg Annual Statistical Indicators 2000–2011 (Jahreszahlen 2000–2011)",
      "url_or_doi": "https://www.duisburg.de/microsites/statistik/Informationslogistik_Statistik/archiv/archiv",
      "justification": "Official historical statistical series published by the City of Duisburg. Contains annual indicators for selected years between 2000 and 2011, including 2000, 2005, 2006, 2007, 2008, and 2009. Particularly useful for longitudinal analysis of population and other municipal indicators associated with urban and community development."
    },
    {
      "title": "Duisburg Annual Statistical Indicators 2005–2012 (Jahreszahlen 2005–2012)",
      "url_or_doi": "https://www.duisburg.de/microsites/statistik/Informationslogistik_Statistik/archiv/archiv",
      "justification": "A historical statistical publication available through Duisburg's official statistics archive. Provides municipal indicators covering the second half of the 2000s and subsequent years. Suitable for examining changes in local living conditions and comparing trends before and after 2010."
    },
    {
      "title": "Duisburg Quarterly Statistical Indicators 2009–2011 (Quartalszahlen 2009–2011)",
      "url_or_doi": "https://www.duisburg.de/microsites/statistik/Informationslogistik_Statistik/archiv/archiv",
      "justification": "Official quarterly statistical records covering the transition from the late 2000s into the early 2010s. Useful for studying short-term developments in municipal indicators and identifying changes around 2009. Complements the annual statistical datasets by offering more frequent observations."
    },
    {
      "title": "Duisburg Population by Neighborhood and Nationality, 2000 (Sozialbericht 2007)",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "The 2007 Social Report includes detailed historical population tables for 2000 covering Duisburg's districts and neighborhoods, including Marxloh, Hamborn, Hochfeld, Rheinhausen, Baerl, and Walsum. Statistics distinguish residents by sex and nationality. These data are particularly suitable for analyzing community composition, migrant populations, and demographic differences between densely populated urban neighborhoods and more peripheral residential areas."
    },
    {
      "title": "Duisburg Employment Statistics by Neighborhood, 2000–2005",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "The 2007 Social Report contains a statistical table on employees subject to social insurance contributions by Duisburg neighborhood for 2000, 2004, and 2005. These historical employment data support comparisons of socioeconomic conditions across neighborhoods and provide evidence about economic restructuring and differences in community living standards during the early 2000s."
    },
    {
      "title": "Duisburg Housing Insecurity Statistics, 2006",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "The 2008 Social Report includes statistics on households threatened by homelessness in 2006, classified by household type, nationality, sex, neighborhood, and district. This information is particularly relevant to housing vulnerability, social exclusion, and inequalities in urban living conditions during the requested period."
    },
    {
      "title": "Duisburg Youth Welfare and Family Support Statistics, 2005–2006",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024",
      "justification": "The 2008 Social Report presents district- and neighborhood-level statistics on youth welfare measures and educational assistance during 2005–2006. These data provide evidence about family support needs, child welfare, and differences in social conditions across Duisburg's communities."
    },
    {
      "title": "Duisburg Historical Municipal Statistics Archive",
      "url_or_doi": "https://www.duisburg.de/microsites/statistik/Informationslogistik_Statistik/archiv/archiv",
      "justification": "The official municipal statistics archive provides access to historical statistical publications, annual figures, and quarterly indicators. It is a useful starting point for locating original data from the 2000s and comparing demographic and socioeconomic developments across time. Some resources are provided as PDF tables rather than machine-readable datasets."
    },
    {
      "title": "Duisburg Open Data Portal",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_i/i-02/opendataportal",
      "justification": "The official municipal open-data portal provides access to datasets on population, administrative geography, and other aspects of city life. Useful for obtaining neighborhood-level geographic and demographic information that can supplement historical analysis. However, the availability of observations specifically from 2000–2009 must be checked for individual datasets."
    },
    {
      "title": "Duisburg Open Geospatial Data: Administrative Boundaries and Population Statistics",
      "url_or_doi": "https://geoportal2.duisburg.de/arcgisserver/rest/services/OpenData/OpenData/MapServer",
      "justification": "An official ArcGIS REST service containing geographic and statistical datasets for Duisburg. It includes neighborhood-related population layers and administrative geography useful for spatial analysis. Although the identified population layers primarily cover later years, geographic information can help map and compare historical community statistics from the 2000s across Duisburg's urban and peripheral neighborhoods."
    },
    {
      "title": "Duisburg in Zahlen: Official Municipal Statistical Publications",
      "url_or_doi": "https://www.duisburg.de/microsites/statistik/Informationslogistik_Statistik/duisburg-in-zahlen/duisburg-in-zahlen",
      "justification": "The official municipal statistical publication series provides structured information about Duisburg's population and urban characteristics. It can support comparisons between historical conditions documented in the 2000s and more recent developments. Historical coverage varies by indicator, so it should be used alongside the archived annual statistics and social reports."
    }
  ]
}
